// CBSE 11 English Core, ch06 "We're Not Afraid to Die... if We Can All Be Together" (Gordon Cook and Alan East) — question bank.
// LITERATURE RULE (D-036): nothing here quotes or closely paraphrases the account. Passages are SOYL commentary
// (passage_origin: soyl-commentary); stems describe events in SOYL's own words. Students read the text in Hornbill.
import { Q, mcq, ar, tf, fb, match, ord, short, long, caseQ, child } from '../../../english-language/cbse-11-english-core-ch01/src/lib.mjs';

const NOTE = "*(This passage is SOYL's commentary on We're Not Afraid to Die… if We Can All Be Together, not an extract from it. Read the text itself in your textbook, Hornbill.)*";
const CASE_STEM = `Read the commentary and answer the questions that follow. ${NOTE}`;
const SCHEME2 = [['Correct point from the account', 1], ['Explanation or inference in own words, within the limit', 1]];
const SCHEME3 = [['Relevant point or incident from the account', 1], ['Explanation or inference linked to the question', 1], ['Expression and accuracy within the word limit', 1]];
const SCHEME5 = [['Content: relevant incidents from the account, accurately used', 2], ['Interpretation or extrapolation: a clear view supported by the account', 1], ['Organisation, format where asked, and expression within the word limit', 2]];
const S2 = { marks: 2, wl: [30, 50], scheme: SCHEME2, time: 150 };
const S3 = { marks: 3, wl: [50, 80], scheme: SCHEME3, time: 240 };
const LA = { marks: 5, wl: [80, 120], scheme: SCHEME5, time: 600 };

// ================================================================ case-based (SOYL commentary), 4 marks each
Q('c_prep', caseQ({
  t: [2, 1], d: 2, c: 'understanding', origin: 'soyl-commentary',
  stem: CASE_STEM,
  passage: "Before the great wave arrives, the account spends time on what the family did to be ready, and this matters more than it first seems. Sail is reduced, a long rope is let out behind the boat to steady it, the life raft is rehearsed, and everyone dresses for the worst. None of this is thrilling, yet it shows people who expect the sea to be dangerous and who do not trust luck to be enough. The authors do not present the family as fearless; they present it as ready. When the wave does strike, the damage is severe, but a crew that has practised meets the shock with action instead of confusion. Preparation does not prevent harm; it makes survival possible.",
  parts: [
    child('a', mcq({ t: 1, d: 1, c: 'recall', stem: 'Which step of the preparation does the commentary say is meant to steady the boat?', opts: ['a long rope let out behind it', 'a second anchor dropped at the bow', 'the engine run at full power', 'the mast taken down'], sol: 'The commentary names the rope let out behind the boat as the steadying measure.' })),
    child('b', mcq({ t: 2, d: 2, c: 'understanding', stem: 'According to the commentary, what does preparation do for the crew?', opts: ['It makes survival possible even though harm still comes', 'It guarantees the boat will not be damaged', 'It removes the need for teamwork', 'It makes the storm last a shorter time'], sol: 'The commentary closes by saying preparation does not prevent harm but makes survival possible.' })),
    child('c', short({ t: 2, d: 3, c: 'understanding', marks: 2, stem: 'The commentary says the authors present the family as ready, not fearless. What difference does it see between the two? Answer in 25-35 words.', model: 'Fearless people feel no danger, while ready people feel it and act on it. The family expects trouble and plans for it, so their courage comes from preparation and not from ignoring the risk.', sol: 'Readiness means expecting danger and acting; fearlessness means not feeling it.', scheme: [['Ready people recognise and expect danger', 1], ['Their courage rests on action and planning', 1]] }),
      [short({ t: 2, d: 3, c: 'analysis', marks: 2, stem: 'The commentary treats the dull routine of preparation as important. Why might a writer include such unexciting detail before a dramatic event? Answer in 25-35 words.', model: 'The routine makes the wave more believable and makes the later teamwork feel earned. A reader who has watched the crew get ready understands why they can respond so quickly once the damage comes.', sol: 'Believability and earned response; credit any reasoned point.', scheme: [['Gives the dramatic event a believable setting', 1], ['Explains why the later response is effective', 1]] })]),
  ],
}));

Q('c_wave', caseQ({
  t: [1, 3], d: 2, c: 'understanding', origin: 'soyl-commentary',
  stem: CASE_STEM,
  passage: "The great wave is the hinge of the account. Until the evening of 2 January the family has been working to prevent trouble; after it, everything is about surviving trouble that has already arrived. The narrator is swept off the deck and sent back aboard by the same sea that wrecks the deck, so the wave takes and gives back in a single movement, which shows how little a person controls out there. What follows tells us more than the blow itself: Mary raises the alarm, the crewmen pump, and the narrator patches the damage. Each person does a different job at the same moment, and nobody waits to be told. The sea is overwhelming; the response to it is organised.",
  parts: [
    child('a', mcq({ t: 1, d: 1, c: 'recall', stem: 'Who raises the alarm after the wave, according to the commentary?', opts: ['Mary', 'Suzanne', 'Jonathan', 'Herb'], sol: 'The commentary names Mary as the one who raises the alarm.' })),
    child('b', mcq({ t: 1, d: 2, c: 'understanding', stem: 'What does the commentary say the wave marks in the account?', opts: ['a change from preventing trouble to surviving it', 'the end of the voyage', 'the first meeting with the crewmen', 'a decision to turn back to Plymouth'], sol: 'The commentary calls the wave the hinge: before it the family prevents trouble, after it they survive trouble.' })),
    child('c', short({ t: 3, d: 3, c: 'understanding', marks: 2, stem: 'Why does the commentary say the response to the wave tells us more than the blow itself? Answer in 25-35 words.', model: 'The blow shows only the strength of the sea. The response shows the people: each of them takes up a separate task at once, which reveals their training, their trust in one another and their calm.', sol: 'The blow shows the sea; the response shows the people.', scheme: [['The blow shows only nature\'s power', 1], ['The response shows the crew\'s qualities (teamwork, calm)', 1]] }),
      [short({ t: 2, d: 3, c: 'understanding', marks: 2, stem: 'Explain in your own words what the commentary means by saying the wave takes and gives back in a single movement. Answer in 25-35 words.', model: 'The same wave that sweeps the narrator off the deck also puts him back on board. The sea can decide life and death in a moment, and the person has no say in it.', sol: 'The wave removes and returns him at once, showing human helplessness.', scheme: [['The wave removes him and returns him in one action', 1], ['It shows how little control a person has', 1]] })]),
  ],
}));

Q('c_child', caseQ({
  t: [3, 2], d: 2, c: 'understanding', origin: 'soyl-commentary',
  stem: CASE_STEM,
  passage: "The children make no speeches, yet the account invites us to measure the adults' courage against theirs. Suzanne is hurt, but she says little about it because she does not want her parents to worry; her bravery lies in what she holds back. Jonathan's remark, which gives the account its title, does the opposite: he says aloud what the adults may be thinking and makes it bearable by adding togetherness. Between them the two children show courage in its quietest and its plainest forms. The adults, respected for their skill, are shown respecting something in the children that skill cannot supply.",
  parts: [
    child('a', mcq({ t: 3, d: 1, c: 'recall', stem: 'Why does Suzanne say little about her injury, according to the commentary?', opts: ['She does not want her parents to worry', 'She does not feel any pain', 'She is afraid of the crewmen', 'She has been told to stay silent'], sol: 'The commentary says she holds back so that her parents will not be worried.' })),
    child('b', mcq({ t: 3, d: 2, c: 'understanding', stem: 'Whose remark gives the account its title, according to the commentary?', opts: ['Jonathan\'s', 'Suzanne\'s', 'Mary\'s', 'Larry\'s'], sol: 'The commentary credits Jonathan\'s remark with giving the account its title.' })),
    child('c', short({ t: 2, d: 3, c: 'understanding', marks: 2, stem: 'How, according to the commentary, do the two children handle fear differently? Answer in 25-35 words.', model: 'Suzanne hides her pain to protect her parents, so her courage is silent. Jonathan speaks his feeling aloud and adds the comfort of being together, so his courage is open.', sol: 'Suzanne is silent; Jonathan speaks.', scheme: [['Suzanne holds back (quiet courage)', 1], ['Jonathan speaks out and adds togetherness (plain courage)', 1]] }),
      [short({ t: 3, d: 4, c: 'analysis', marks: 2, stem: 'The commentary says the adults respect something in the children that skill cannot supply. What might that be? Answer in 25-35 words.', model: 'It may be the children\'s steadiness without training. The adults have seamanship to lean on, but the children have only trust and love, and still behave calmly, which gives the adults fresh strength.', sol: 'A reasoned suggestion such as steadiness, trust or love.', scheme: [['Names a quality (steadiness, trust or love)', 1], ['Contrasts it with skill', 1]] })]),
  ],
}));

Q('c_nav', caseQ({
  t: [3, 2], d: 2, c: 'understanding', origin: 'soyl-commentary',
  stem: CASE_STEM,
  passage: "In the days after the night of pumping, the account slows down. The narrator, exhausted, works out the boat's position with great care, because the family's hope rests on a small island that a modest error could hide from view. The tension here is quiet: no wave, no crash, only calculation and patience. Suzanne's drawing for her parents belongs to this stretch. It does not alter the boat's position, but it alters the mood aboard, reminding the adults that they are parents as well as sailors. Leadership in these pages looks less like courage in a storm and more like steady attention when tired.",
  parts: [
    child('a', mcq({ t: 1, d: 1, c: 'recall', stem: 'What does the narrator carefully work out in these days, according to the commentary?', opts: ['the boat\'s position', 'the cost of repairs', 'the date of the next storm', 'the weight of the cargo'], sol: 'The commentary says he works out the boat\'s position.' })),
    child('b', mcq({ t: 2, d: 2, c: 'understanding', stem: 'How does the commentary describe the tension in this stretch of the account?', opts: ['quiet, made of calculation and patience', 'loud, full of crashing waves', 'comic, full of jokes', 'absent altogether'], sol: 'The commentary calls the tension quiet: no wave, only calculation and patience.' })),
    child('c', short({ t: 3, d: 3, c: 'understanding', marks: 2, stem: 'Why does the commentary say the drawing changes the mood aboard but not the boat\'s position? Answer in 25-35 words.', model: 'A drawing cannot move a boat or find an island, but it can make people smile and remember who they are. It lightens the mood of the adults without touching the practical problem.', sol: 'The drawing helps feeling, not navigation.', scheme: [['It has no practical effect on position', 1], ['It lifts the mood and reminds the adults they are parents', 1]] }),
      [short({ t: 3, d: 3, c: 'analysis', marks: 2, stem: 'The commentary says leadership here is steady attention when tired. Why might this be harder than courage in a storm? Answer in 25-35 words.', model: 'In a storm, danger forces energy out of a person. During long tired days nothing forces it, so the narrator must keep himself careful with no help from excitement, and a small slip could be fatal.', sol: 'Sustained effort without adrenaline; credit a reasoned view.', scheme: [['Storm danger supplies urgency; tired days do not', 1], ['Sustained care is needed and errors cost heavily', 1]] })]),
  ],
}));

Q('c_land', caseQ({
  t: [2, 1], d: 2, c: 'understanding', origin: 'soyl-commentary',
  stem: CASE_STEM,
  passage: "The landing is quiet in a different way. After days of strain the family reaches the island base, and the account closes on welcome rather than triumph. Jonathan's praise of his father is brief and sincere; it comes as land at last comes into view, when a child can say simply what he felt. The island's small community offers shelter, and with it a reminder that the sea, for all its power, is not the whole world. The ending completes the promise of the title: the family has stayed together, and the people ashore receive them as one household. The authors leave out any boasting about the feat, and that omission is itself a statement of what they value.",
  parts: [
    child('a', mcq({ t: 1, d: 1, c: 'recall', stem: 'Who receives the family on the island, according to the commentary?', opts: ['the island\'s small community', 'a rescue ship\'s crew', 'a team of reporters', 'the narrator\'s relatives'], sol: 'The commentary says the island\'s small community offers shelter.' })),
    child('b', mcq({ t: 2, d: 2, c: 'understanding', stem: 'How does the commentary describe the way the account ends?', opts: ['on welcome rather than triumph', 'on a boast about the feat', 'on a new storm', 'on a quarrel among the crew'], sol: 'The commentary says the account closes on welcome, not triumph.' })),
    child('c', short({ t: 2, d: 3, c: 'understanding', marks: 2, stem: 'What does the commentary mean by saying the ending completes the promise of the title? Answer in 25-35 words.', model: 'The title speaks of being together, and the ending shows the family still together on land, received as one household. What the title promised in danger is kept in safety.', sol: 'The family remains together and is welcomed together.', scheme: [['The title is about being together', 1], ['The ending shows the family together and welcomed as one', 1]] }),
      [short({ t: 2, d: 4, c: 'analysis', marks: 2, stem: 'The commentary calls the lack of boasting a statement of the authors\' values. What values might it reveal? Answer in 25-35 words.', model: 'It may reveal modesty and a belief that people matter more than achievements. By stressing welcome and family, the authors suggest that the survival of the household is worth more than the feat itself.', sol: 'Modesty, family over achievement; credit a reasoned reading.', scheme: [['Names a value (modesty, family, humility)', 1], ['Links it to the omission of boasting', 1]] })]),
  ],
}));

// ================================================================ MCQ (opts[0] is the correct option; order is shuffled by the library)
Q('m_authors', mcq({ t: 1, d: 1, c: 'recall', stem: 'Which pair of writers is credited with the Hornbill prose piece about a family caught in a storm in the southern Indian Ocean?', opts: ['Gordon Cook and Alan East', 'Gordon Cook and Ruskin Bond', 'Alan East and Daphne du Maurier', 'Jack London and Alan East'], sol: 'The account is by Gordon Cook and Alan East.' }));
Q('m_start', mcq({ t: 1, d: 1, c: 'recall', stem: 'From which English port did the family set sail in July 1976?', opts: ['Plymouth', 'Southampton', 'Liverpool', 'Dover'], sol: 'They sailed from Plymouth.' }));
Q('m_aim', mcq({ t: 1, d: 1, c: 'recall', stem: 'What did the narrator hope to achieve with the voyage?', opts: ['to repeat the round-the-world voyage of Captain James Cook, made two hundred years earlier', 'to set a speed record for crossing the Indian Ocean', 'to search for a lost island', 'to deliver cargo to Cape Town'], sol: 'He hoped to repeat Captain Cook\'s round-the-world voyage of two hundred years before.' }));
Q('m_crew', mcq({ t: 1, d: 1, c: 'recall', stem: 'Which description of the two crewmen who joined the family for the hardest part of the voyage is correct?', opts: ['Larry Vigil, an American, and Herb Seigler, a Swiss', 'Larry Vigil, a Swiss, and Herb Seigler, an American', 'Two brothers from Plymouth', 'Two members of the island base'], sol: 'Larry Vigil was an American and Herb Seigler a Swiss.' }));
Q('m_firstleg', mcq({ t: 1, d: 1, c: 'recall', stem: 'Where did the first leg of the voyage end, before the family sailed east into the southern Indian Ocean?', opts: ['Cape Town', 'Sydney', 'Ile Amsterdam', 'Cape Horn'], sol: 'The first leg ended at Cape Town, from where they sailed east.' }));
Q('m_ile', mcq({ t: 1, d: 1, c: 'recall', stem: 'What kind of place was Ile Amsterdam, the island the narrator hoped to reach?', opts: ['a small French island with a scientific base', 'a large port city', 'an uninhabited rock', 'a Swiss mountain village'], sol: 'It is a small French island with a scientific base.' }));
Q('m_suz', mcq({ t: 3, d: 2, c: 'analysis', stem: 'Meera, an imagined girl on a school trip, hides a sprained wrist because she is afraid of being sent home early. How does her silence differ most from Suzanne\'s?', opts: ['Meera keeps quiet to protect her own plans; Suzanne kept quiet to spare her parents extra worry', 'Meera\'s injury is milder, so her silence is the braver of the two', 'There is no real difference: both hide an injury to keep themselves out of trouble', 'Suzanne kept quiet only because an adult had told her to stay still'], sol: 'The two silences look alike but point in opposite directions: Meera protects herself, while Suzanne protected her parents, who were fighting for the boat. Suzanne was not avoiding trouble or obeying an order, and a milder injury does not make a self-protective silence braver.' }));
Q('m_card', mcq({ t: 3, d: 2, c: 'recall', stem: 'What did Suzanne give her father during the difficult days that followed?', opts: ['a card she had drawn, showing funny pictures of her parents', 'a letter for the island community', 'a map of the Indian Ocean', 'a toy boat she had made'], sol: 'She gave him a drawn card with funny pictures of her parents.' }));
Q('m_mary', mcq({ t: 3, d: 1, c: 'recall', stem: 'Who was Mary in the account?', opts: ['the narrator\'s wife', 'the narrator\'s sister', 'the crew\'s cook', 'a scientist on the island'], sol: 'Mary was the narrator\'s wife and the children\'s mother.' }));
Q('m_form', mcq({ t: 1, d: 3, c: 'analysis', stem: 'In a first-person account of a real voyage, readers know from the start that the narrator lived to write it. How, then, does this account still hold its suspense?', opts: ['The question shifts from whether he lives to whether the boat holds and the whole family and crew come through, and how', 'It hints throughout that the narrator may not have survived', 'It leaves the ending open, so readers never learn whether the family reached land', 'It tells the events out of order, beginning with the landing'], sol: 'The narrator\'s own survival is settled by the form, so the tension moves to the others aboard and to the boat itself: will the damage hold, will they find the island, will everyone come through. The account runs in time order and ends with a clear landing, and it never pretends the narrator might be dead.' }));
Q('m_prep', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Why did the family reduce sail, let out a rope behind the boat and practise with the life raft on 2 January?', opts: ['The waves were becoming enormous and they were getting ready for the worst', 'They had already been damaged and wanted to repair the boat', 'They were hoping to reach land by evening', 'The crewmen had demanded these steps'], sol: 'The steps were precautions taken as the waves grew; the damage came later in the evening.' }));
Q('m_welcome', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Mary appears in the account mainly at the moment she raises the alarm. A student concludes that she played only a small part in the family\'s survival. What is the main flaw in this reasoning?', opts: ['The account is told by the narrator, who reports mostly what he himself saw and did, so a short record of Mary\'s actions does not prove a small part', 'Mary was not aboard the boat during the storm', 'Mary did the navigation, and the narrator hides this', 'Raising the alarm was the only task that mattered, so her part was the largest of all'], sol: 'A first-person narrator records his own actions most fully; what he leaves out is not evidence that nothing happened. Mary was aboard, the narrator did the navigating, and claiming her alarm outweighs the pumping and patching swaps one overstatement for another.' }));
Q('m_cf_narr', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Suppose Mary had written the account instead of her husband. Which moment of the wave episode could she least easily describe from her own experience?', opts: ['the narrator being swept off the deck and carried back aboard', 'the water pouring into the cabins below', 'the crewmen pumping hour after hour', 'the alarm she herself raised about the water'], sol: 'The fall and the return are felt from the inside only by the man they happened to; anyone else, Mary included, could report them only as something seen or told. The water below, the pumping and her own alarm were things she could witness or do herself.' }));
Q('m_cf_crew', mcq({ t: 3, d: 3, c: 'analysis', stem: 'Imagine the family had sailed on from Cape Town without Larry and Herb. Which consequence follows most directly from what happened after the wave?', opts: ['Pumping out the water and covering the openings could not both have gone on at full strength at the same time', 'The wave would have done less damage to a boat carrying fewer people', 'There would have been no one aboard to raise the alarm', 'The family would certainly have turned back before the storm'], sol: 'After the wave two jobs had to run together: the crewmen pumped while the narrator covered the openings. Without them, the same hands would have had to switch between the two. Mary, not the crew, raised the alarm; the size of the crew does not change a wave; and nothing in the account says the family would have turned back.' }));
Q('m_cf_complain', mcq({ t: 3, d: 2, c: 'understanding', stem: 'If Suzanne had cried out about her injury, which effect on the crisis is most likely?', opts: ['The parents\' attention would be divided between her and the leak', 'The boat would have stopped taking in water', 'The crewmen would have left the pumps', 'The storm would have ended sooner'], sol: 'Her silence spared her parents extra worry at a moment when they were needed on deck. Had she cried out, they would have had to share their attention. The weather and the pumps do not respond to her voice.' }));
Q('m_remove_card', mcq({ t: 2, d: 3, c: 'analysis', stem: 'A student argues that in the worst days the children did not merely avoid adding to the adults\' worries but actively lifted their spirits. Which detail, if removed, would weaken this reading most?', opts: ['Suzanne\'s drawn card with funny pictures of her parents', 'Suzanne saying little about how badly she was hurt', 'Jonathan\'s praise of his father when the island came into view', 'the children staying below deck during the storm'], sol: 'The reading claims more than quiet bravery: it says the children raised morale while the danger lasted. The card is the one detail that does this. Suzanne\'s silence only avoids adding worry, which the reading sets aside; the praise comes once land is in sight, after the worst days; staying below is not an act of encouragement at all.' }));
Q('m_flaw_leader', mcq({ t: 3, d: 3, c: 'analysis', stem: 'A student claims that the narrator is a good leader because he does the hardest physical work aboard himself. What is the main flaw in this claim?', opts: ['His leadership lies less in labour than in sharing out the tasks and finding the island; the crewmen did the long pumping', 'He does no physical work at all, so the claim is wholly false', 'The claim is fully right, since he also pumps alone through the night', 'Leadership cannot be judged in an account written by the leader himself'], sol: 'The claim is partly right: he covers the openings himself. Its flaw is where it places his leadership. The hours of pumping belong to Larry and Herb, and what only he does is plan, patch and navigate. He did physical work, he did not pump alone, and a first-person account can still be weighed against the events it reports.' }));
Q('m_compare_cap', mcq({ t: 3, d: 2, c: 'understanding', stem: 'Captain Rao, an imagined skipper, sends the whole crew below and handles every emergency alone. How does the narrator\'s approach differ?', opts: ['Several people work at separate tasks at the same time', 'He refuses all help from Mary', 'He leaves the repairs to the children', 'He steers the boat while the crew sleep'], sol: 'In the account, the crewmen pump, Mary raises the alarm and the narrator patches, so work is shared. Nothing suggests he refuses help or uses the children.' }));
Q('m_end_cf', mcq({ t: 2, d: 2, c: 'understanding', stem: 'If the account had stopped at the night of pumping, without the days that follow and the landing, what would the title lose most?', opts: ['the evidence that being together led to survival and welcome', 'the name of the boat', 'the list of crewmen', 'the date of the voyage'], sol: 'The title speaks of togetherness in danger. The later days and the landing show what that togetherness led to; without them the reader would not know the outcome. The name of the boat, the crewmen and the date do not carry the title\'s meaning.' }));
Q('m_why_title', mcq({ t: 2, d: 4, c: 'analysis', stem: 'The account takes its title from a child\'s remark, not from anything the adults say or do. Which is the best reason for that choice?', opts: ['It puts the steadiest words in the youngest mouth, so the courage comes from a surprising source and is shared by the family', 'It signals that the account will be told through the children\'s eyes', 'It prepares the reader for an ending in which the family is lost', 'It shows that the children understood the danger better than the adults did'], sol: 'A child\'s words of comfort reverse what we expect in a crisis and make togetherness, not seamanship, the heart of the account. The father narrates, so the title is not a clue to point of view; the family survives, so it does not foreshadow loss; and nothing suggests the children grasped the danger better than the skilled adults.' }));
Q('m_panic', mcq({ t: 3, d: 3, c: 'analysis', stem: 'Suzanne\'s parents learn how badly she was hurt only some time after the wave. What does this delay most suggest about the first hours after the wave?', opts: ['Saving the boat took the adults\' attention so fully that a hurt child who kept quiet could go unnoticed', 'Her injuries were too slight for anyone to notice', 'Suzanne was hurt only later, in the days after the wave', 'The family had no means of treating injuries aboard'], sol: 'Her injuries were worse than she let on, and she had been hurt in the wave itself, so the delay says something about the adults\' situation: every hand and every thought was on the leaking boat, which is exactly what her silence counted on. Nothing in the account is about a lack of medical supplies.' }));
Q('m_flaw_children', mcq({ t: 3, d: 3, c: 'analysis', stem: 'A student claims that the children stayed calm only because they did not understand how serious the danger was. Which detail from the account best shows the flaw in this claim?', opts: ['Suzanne said little about her injuries because she did not want to add to her parents\' worries', 'Suzanne drew funny pictures of her parents', 'Jonathan praised his father once the island was in sight', 'The children stayed below deck during the storm'], sol: 'To keep quiet so as not to burden her parents, Suzanne had to grasp how hard they were fighting and why, so her calm was a choice made with understanding. Funny drawings, praise after the danger and staying below are all consistent with a child who did not understand, so they cannot refute the claim.' }));
Q('m_ev_suz', mcq({ t: 3, d: 4, c: 'evaluation', stem: 'Which judgement of Suzanne\'s decision to say little about her injuries weighs the evidence most fairly?', opts: ['It was loving and brave, though keeping quiet about a head injury carried a real risk', 'It was loving and brave, and carried no risk, because her injuries were slight', 'It was sensible only because her parents had nothing else to attend to at the time', 'It was a mistake, because it delayed the family\'s arrival at the island'], sol: 'A fair judgement credits her motive and also counts the risk, since her injuries proved worse than she let on. Her injuries were not slight, her parents were fighting for the boat, and her silence had nothing to do with when they reached the island.' }));
Q('m_ev_theme', mcq({ t: 2, d: 4, c: 'evaluation', stem: 'Reader A says the account is mainly about the danger of the sea. Reader B says it is mainly about how a family and crew hold together. Which judgement weighs the evidence best?', opts: ['B is better supported: most of the account follows how the people respond, and the danger is what tests them', 'A is better supported: the wave is the most vivid moment, so it must be the main subject', 'A is better supported: the title names death, so danger is its main concern', 'Neither: the account is mainly a record of how to navigate'], sol: 'The sea supplies the test, but most of the account shows the response to it, and the title ties death to a condition, being together. Reader A mistakes the most dramatic moment, or one word of the title, for the main subject; navigation is one part of the response, not the whole.' }));
Q('m_inf_praise', mcq({ t: 3, d: 3, c: 'analysis', stem: 'At the end Jonathan praises his father as a captain, not only as a father. Which reading of that word is best supported by when the praise comes?', opts: ['It credits the skill that found the island, the part of his father\'s work that the boy could see succeed', 'It repeats something the crewmen had told him to say', 'It shows he valued his father only for his skill and not for his care', 'It is a joke about how nearly they had missed the island'], sol: 'The praise comes as the island comes into view, the moment the narrator\'s careful navigation is proved right, so the word captain points to that success. Nothing suggests the crew prompted him, the word adds to his love rather than replacing it, and the moment is one of relief, not teasing.' }));
Q('m_app_prep', mcq({ t: 2, d: 3, c: 'application', stem: 'A coach preparing a team for a week-long tournament wants to borrow from the account, especially from the days after the wave rather than the wave itself. Which plan does that best?', opts: ['Plan for steady effort shared in turns over many days, and for ways of keeping spirits up when everyone is tired', 'Train hard for the first match, since the rest will follow once it is won', 'Rely on the strongest player to carry the team throughout', 'Avoid talking about difficulties so that nobody worries'], sol: 'The days after the wave are about endurance: long, shared work and small acts that lift morale. A plan built only on the first test or on one star player copies the wrong lesson, and Suzanne\'s silence was a child\'s choice in a crisis, not a rule for keeping a team informed.' }));
Q('m_inf_pump', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Right after the wave, the narrator covers the openings in the deck with canvas instead of trying to rebuild the broken wood. What does this choice best suggest about his thinking in those first hours?', opts: ['Keeping the water out quickly with what was at hand mattered more than a lasting repair, which that sea would not allow', 'He did not expect the boat to need any further repair', 'He wanted to hide the damage from the children', 'He trusted the pumps to remove all the water, so the openings hardly mattered'], sol: 'A quick cover slows the water at once, while a real repair would take time, materials and calm weather that he did not have. Further damage did follow, nothing suggests he was hiding anything, and if the openings hardly mattered he would not have covered them.' }));
Q('m_nav_cf', mcq({ t: 1, d: 3, c: 'analysis', stem: 'A student says that once the pumping had the water under control, the danger was over, and the narrator\'s navigation only decided where they would land. What is the main flaw in this claim?', opts: ['The damaged boat could not stay afloat for ever; pumping bought time, and finding the island turned it into survival', 'The pumping never brought the water down at all', 'The island was easy to see from far off, so navigation mattered little', 'The crewmen, not the narrator, did the navigating'], sol: 'Controlling the water kept the boat afloat for the moment, but it was still damaged and the weather turned bad again, so survival depended on reaching land. The water was in fact brought down, the island was small and easy to miss, and the narrator did the navigating.' }));

// ================================================================ assertion-reason
Q('ar_prep', ar({ t: 1, d: 2, c: 'understanding', verdict: 'both-true-explains', a: 'On 2 January the family reduced sail and rehearsed the life-raft routine.', r: 'The waves that day had become enormous.', sol: 'Both are true, and R is the reason for A: the growing waves prompted the precautions.' }));
Q('ar_crew', ar({ t: 3, d: 1, c: 'understanding', verdict: 'A-true-R-false', a: 'Larry and Herb were an important part of the team that kept the boat afloat.', r: 'They were the narrator\'s relatives, travelling with the family.', sol: 'A is true: they pumped for hours. R is false: Larry was an American and Herb a Swiss who joined as crew.' }));
Q('ar_cook', ar({ t: 2, d: 2, c: 'understanding', verdict: 'A-false-R-true', a: 'The account shows that the voyage was never dangerous for the family.', r: 'The boat had been tested in gales before the voyage began.', sol: 'A is false: a huge wave wrecked the deck and water poured in. R is true: the boat was professionally built and tested, but that did not remove the danger.' }));
Q('ar_praise', ar({ t: 3, d: 3, c: 'analysis', verdict: 'both-true-not-explains', a: 'Jonathan praises his father as a captain at the moment the island comes into view.', r: 'Earlier, when the danger returned, Jonathan had spoken of not fearing death if the family stayed together.', sol: 'Both are true, but R does not explain A. The earlier remark shows a child finding comfort in togetherness while the danger lasts; the praise is set off by the sighting of the island, which proves the narrator\'s navigation right. The two moments share the same trust, but the reason for the praise lies in the sighting, not in the earlier remark.' }));
Q('ar_remedy', ar({ t: 1, d: 2, c: 'understanding', verdict: 'both-true-not-explains', a: 'The narrator went over the side in the wave and came back aboard when the boat righted.', r: 'The same wave left the deck badly damaged and let water in.', sol: 'Both are true, but the damage does not explain why he returned aboard; the boat righting does. R tells us about another result of the wave.' }));
Q('ar_gale', ar({ t: 2, d: 2, c: 'understanding', verdict: 'both-true-explains', a: 'Good preparation did not spare the family from serious damage in the account.', r: 'Preparation can reduce what harm does, but it cannot remove the sea\'s power.', sol: 'Both are true, and R is the general reason behind A: practice and a sound boat helped them survive but could not stop a huge wave from doing damage.' }));

// ================================================================ true-false, fill-blank, match, ordering
Q('tf_ile', tf({ t: 1, d: 1, c: 'recall', ans: true, stem: 'The island the narrator hoped to reach had a scientific base and belonged to France.', sol: 'Ile Amsterdam is a small French island with a scientific base.' }));
Q('tf_wave', tf({ t: 1, d: 2, c: 'recall', ans: false, stem: 'The enormous wave that wrecked the deck struck in the early morning of 2 January.', sol: 'It struck in the evening of 2 January, after the day of preparation.' }));
Q('tf_exam', tf({ t: 4, d: 1, c: 'understanding', ans: false, stem: 'In a diary entry written as a character, you may change the facts of the voyage if it makes the entry more dramatic.', sol: 'An extrapolation must stay faithful to the facts and fit the characters; only feelings and small details may be added.' }));
Q('fb_start', fb({ t: 1, d: 1, c: 'recall', stem: 'The family began the voyage from ___, in England.', acc: [['Plymouth']], sol: 'They sailed from **Plymouth**.' }));
Q('fb_crew', fb({ t: 1, d: 2, c: 'recall', stem: 'The two crewmen were Larry Vigil, an American, and Herb ___, a Swiss.', acc: [['Seigler']], sol: 'The Swiss crewman was Herb **Seigler**.' }));
Q('match_people', match({ t: 3, d: 2, c: 'understanding', stem: 'Match each person with the part he or she plays in the account.', pairs: [
  ['Mary', 'raises the alarm after the wave'],
  ['Larry and Herb', 'pump the water out for hours'],
  ['Suzanne', 'keeps her injury quiet and draws a card'],
  ['Jonathan', 'gives the account its title with his remark'],
], sol: 'Each person is linked to the incident with which the account associates him or her.' }));
Q('match_events', match({ t: 1, d: 2, c: 'understanding', stem: 'Match each stage of the voyage with what happens in it.', pairs: [
  ['After Cape Town', 'strong gales and huge seas in the southern Indian Ocean'],
  ['Earlier on 2 January','sail reduced, a rope let out and drills rehearsed'],
  ['Evening of 2 January', 'the great wave strikes and the deck is damaged'],
  ['Days afterwards', 'careful navigation towards a small island'],
], sol: 'The stages run from the gales after Cape Town through the preparations and the wave to the final approach.' }));
Q('ord_events', ord({ t: 1, d: 2, c: 'understanding', stem: 'Put these events of the voyage in the order in which they happen.', items: [
  'The family sets sail from Plymouth',
  'The first leg ends at Cape Town',
  'On 2 January the crew prepare for enormous waves',
  'The wave strikes and the pumping begins',
  'Suzanne gives her father her drawn card',
  'The family lands and is welcomed on the island',
], sol: 'The voyage begins at Plymouth, reaches Cape Town, meets the storm, survives the wave and the long struggle, and ends with the landing.' }));

// ================================================================ short answers, 2 marks (30-50 words)
Q('s2_why_prep', short({ ...S2, t: 1, d: 2, c: 'understanding', stem: 'Name two steps the family took as the waves grew on 2 January and say what they show about the crew. Answer in 30-50 words.', model: 'They reduced sail and went through the life-raft routine, and they also put on protective clothing. These steps show a crew that expected danger and prepared for it, instead of waiting to see what the sea would do.', sol: 'Two steps (reduced sail, a rope, drills, clothing) + what they show (readiness).' }));
Q('s2_suz', short({ ...S2, t: 3, d: 1, c: 'recall', stem: 'What happened to Suzanne in the wave episode, and how did she behave afterwards? Answer in 30-50 words.', model: 'Suzanne was hurt in the wave, with a swelling on her head and a cut. She said little about it, because she did not want to add to her parents\' worries at a moment when they were fighting to save the boat.', sol: 'Injury (head swelling, cut) + her silence and its reason.' }));
Q('s2_pump', short({ ...S2, t: 1, d: 2, c: 'understanding', stem: 'After the wave, who did what to save the boat? Answer in 30-50 words.', model: 'Larry and Herb pumped out the water for hours, while the narrator covered the broken parts of the deck with canvas. Mary had already raised the alarm that the boat was taking in water, and later an electric pump was set up.', sol: 'Roles: crewmen pump; narrator patches; Mary alarm; electric pump later.' }));
Q('s2_cf_cap', short({ ...S2, t: 3, d: 3, c: 'analysis', stem: 'Suppose the narrator had been too badly hurt in the wave to do anything afterwards. Which of his tasks could the others most easily have taken over, and which least easily? Explain. Answer in 30-50 words.', model: 'Covering the openings could have been taken over most easily, since Mary or a crewman could see the damage and fix canvas over it. Working out the position was hardest to replace: no one else is shown doing it, and a small error could miss the island.', sol: 'Easiest: covering the openings (visible, physical) + least easy: navigation (his skill alone; errors fatal), each with a reason.', scheme: [['Names covering the openings (or another physical task) as easiest, with a reason', 1], ['Names navigation as hardest to replace, with a reason', 1]] }));
Q('s2_two_cards', short({ ...S2, t: 3, d: 3, c: 'analysis', stem: 'Suzanne\'s card shows her parents as funny figures. Why might a comic picture of the parents themselves be a more fitting comfort at that point than, say, a drawing of the boat or of the island they hoped to reach? Answer in 30-50 words.', model: 'A drawing of the boat would recall the damage, and one of the island might stand for a hope that could still fail. Making her parents look funny lets them laugh at themselves, as people and not only as worn-out sailors.', sol: 'The boat recalls damage; the island is an uncertain hope; laughing at themselves lifts the parents as people.', scheme: [['Explains why the boat or the island would be a weaker comfort', 1], ['Explains what laughing at themselves gives the parents', 1]] }));
Q('s2_ap_trek', short({ ...S2, t: 2, d: 2, c: 'application', stem: 'A trek leader learns that a young member has hurt her ankle but is hiding it so that the group will not worry. Using the account of Suzanne, say what the leader should do and why. Answer in 30-50 words.', model: 'The leader should thank her quietly, check the injury and make sure it is treated. Her motive is kind, as Suzanne\'s was, but hidden injuries can worsen, and a group that knows the truth can plan the route better.', sol: 'Respect the motive + act on the injury + give a reason (hidden injuries worsen; the group can plan).' }));
Q('s2_ev_hide', short({ ...S2, t: 3, d: 2, c: 'evaluation', stem: 'Was Suzanne right to hide her injury? Give one reason for and one reason against. Answer in 30-50 words.', model: 'For: her silence spared her parents extra worry while they were fighting to save the boat. Against: an untreated head injury could have grown worse, and her parents, had they known, might have cared for her sooner.', sol: 'One reason each way, each linked to the account; credit a closing view.' }));
Q('s2_island', short({ ...S2, t: 1, d: 3, c: 'analysis', stem: 'Imagine the narrator had decided to sail on to a large port many days away instead of aiming for a small island. Weigh one advantage and one danger of that plan, using what happened to the boat. Answer in 30-50 words.', model: 'A large port would be hard to miss and could offer proper repairs. But the boat was badly damaged, the crew were worn out from pumping and the weather turned bad again, so a long passage might have ended before they reached it.', sol: 'Advantage (a big target, repairs) + danger (damaged boat, tired crew, bad weather over many days), both tied to the account.', scheme: [['One advantage of the larger, distant port', 1], ['One danger, linked to the state of the boat or crew in the account', 1]] }));
Q('s2_team', short({ ...S2, t: 2, d: 3, c: 'analysis', stem: 'The great wave struck in the evening, not in daylight. Give two reasons why this timing made the teamwork that followed harder. Answer in 30-50 words.', model: 'First, the openings had to be found and covered and the pumps kept going in darkness, on a wrecked and heaving deck. Second, everyone was already tired from a day of preparing, yet the work had to go on all night without rest.', sol: 'Two reasons: darkness makes repairs and pumping harder; the crew are already tired and must work through the night.', scheme: [['Darkness hampers the repairs and pumping', 1], ['Tiredness after a day of preparation, with no rest through the night', 1]] }));
Q('s2_jon_praise', short({ ...S2, t: 3, d: 3, c: 'evaluation', stem: 'Jonathan praised his father only after the island was sighted. Does that make the praise less sincere? Give your view in 30-50 words.', model: 'I think not. A child may only feel free to say such a thing once the danger has passed. The praise is also earned by the days of care that came before it, so the timing shows relief and not flattery.', sol: 'A clear view supported by reasons; accept a reasoned opposite view.' }));

// ================================================================ short answers, 3 marks (50-80 words)
Q('s3_summary', short({ ...S3, t: 1, d: 2, c: 'understanding', stem: 'Describe in your own words what happened on the evening of 2 January and in the hours that followed. Answer in 50-80 words.', model: 'On the evening of 2 January an enormous wave struck the boat. The narrator was carried off the deck and returned aboard as the boat righted, the deck was badly damaged and water poured in. Mary raised the alarm, Larry and Herb pumped for hours, and the narrator covered the holes with canvas. They kept pumping through the night.', sol: 'The wave and the fall; the damage; the roles; the night of pumping.' }));
Q('s3_themes', short({ ...S3, t: 2, d: 2, c: 'understanding', stem: 'Explain two ways in which courage is shown in the account. Answer in 50-80 words.', model: 'Courage is shown by the adults, who keep working at the pumps and the repairs while exhausted. It is also shown by the children: Suzanne hides her injury to spare her parents, and Jonathan speaks of being together instead of being afraid. Both kinds of courage help the family keep going through the long days.', sol: 'Two kinds of courage, each with an incident.' }));
Q('s3_lead_cf', short({ ...S3, t: 3, d: 3, c: 'analysis', stem: 'Compare the part played by the narrator with that of the crewmen after the wave, on two points: kind of work and kind of responsibility. Answer in 50-80 words.', model: 'The crewmen did physical work: they pumped for hours, which needed strength and stamina. The narrator did a mix of tasks, covering the holes with canvas and later working out the position of the boat. His responsibility was wider: he had to plan the way to safety, while the crewmen had to keep water out of the boat.', sol: 'Kind of work (pumping v patching and navigating) + kind of responsibility (keeping water out v finding safety).' }));
Q('s3_children_adults', short({ ...S3, t: 3, d: 3, c: 'analysis', stem: 'Jonathan speaks twice at important moments: the remark that gives the account its title, and his praise of his father at the end. Compare what each moment shows about him, and say what has changed between them. Answer in 50-80 words.', model: 'His remark comes when the danger has returned and death seems possible: it shows a young child facing the worst and finding comfort in the family staying together. His praise comes as the island appears: it shows relief and pride in his father\'s skill. Between the two, fear has given way to trust that has been proved right, and his attention has moved from the family to his father\'s achievement.', sol: 'The remark: facing danger, comfort in togetherness. The praise: relief, pride in the father\'s skill. The change: fear to vindicated trust.', scheme: [['What the remark shows, placed in its moment', 1], ['What the praise shows, placed in its moment', 1], ['What has changed between them, within the word limit', 1]] }));
Q('s3_ap_trip', short({ ...S3, t: 2, d: 3, c: 'application', stem: 'A school group is stranded overnight by floods on a hill road. Apply two ideas from the account to advise its leader. Answer in 50-80 words.', model: 'The leader should first prepare the group for the worst: share the emergency supplies and agree on roles. Then she should divide the work, as the crew did, so that everyone has a task. She should also keep morale up with small, cheerful gestures, as Suzanne\'s card did, and avoid showing panic.', sol: 'Two ideas applied to the new case, each with a reason.' }));
Q('s3_ev_title', short({ ...S3, t: 2, d: 4, c: 'evaluation', stem: 'Is the title a good one for this account? Weigh one point in favour against one against. Answer in 50-80 words.', model: 'In favour: the title is a child\'s remark and sums up the account\'s central idea, that togetherness gives courage. Against: it names death, which may suggest a tragedy, though the family survives. On balance, I think it is a good title, because it makes the reader curious and the ending shows what togetherness achieved.', sol: 'One point each way + a balanced conclusion.' }));

// ================================================================ long answers, 5 marks (80-120 words)
Q('l_diary', long({ ...LA, t: 4, d: 3, c: 'application', bloom: 'create', stem: 'Imagine you are the narrator. Write a diary entry for the day the family was welcomed ashore on Ile Amsterdam, in 80-120 words.', model: 'Night, on Ile Amsterdam\n\nDear Diary,\n\nWe are ashore at last, and I cannot quite believe it. After days of pumping and careful reckoning, the island came into sight, and today the people at the base welcomed us warmly. Mary and I held the children for a long time. I am proud of Larry and Herb, who never gave up the pumps. Jonathan praised me as a captain, but the truth is that all of us brought this boat in. Tonight the ground does not move, and I mean to sleep soundly.', sol: 'Diary format (day, time, salutation, first person, reflective tone). Content must fit the account: arrival at the island, the welcome, the crew\'s work, the family. Credit extrapolated feelings that suit the facts.' }));
Q('l_letter', long({ ...LA, t: 4, d: 3, c: 'application', bloom: 'create', stem: 'Imagine you are Larry Vigil. Write a letter to a friend in the United States describing the night after the great wave, in 80-120 words.', model: 'Dear Tom,\n\nI am writing from a small island in the southern Indian Ocean, safe and very tired. A huge wave hit our boat on the evening of 2 January, and water poured in. Herb and I pumped for hours while the skipper covered the holes with canvas. His wife called out the alarm, and the two children stayed calm, which shamed me a little. By morning we had an electric pump working. I have never worked so hard in my life.\n\nYour friend,\nLarry', sol: 'Letter format (salutation, body, close). Content: the wave, the pumping, the patches, the family, the electric pump. Tone: informal and relieved; extrapolated detail should fit the facts.' }));
Q('l_speech', long({ ...LA, t: 4, d: 3, c: 'application', bloom: 'create', stem: 'You are asked to speak in your school assembly on what courage means. Write the speech in 80-120 words, drawing on one episode from the account.', model: 'Good morning, respected teachers and friends. Courage is not always loud. In an account of a family caught in a storm at sea, a young girl is hurt but says little about it, because she does not want to worry her parents. Her brother, in the same danger, speaks about being together. Neither shouts, yet both help the adults carry on. From them I learn that courage can be quiet, and that caring for others is part of it. Let us remember this when we are tempted to complain. Thank you.', sol: 'Speech format (greeting, topic, one episode used well, lessons, call to action, thanks). Content must fit the account; credit a persuasive tone.' }));
Q('l_sketch', long({ ...LA, t: 3, d: 4, c: 'analysis', stem: 'Imagine Captain Rao, a skipper who gives orders loudly, takes all decisions alone and never speaks to his crew about the danger. Compare him with the narrator on two criteria: how each leads in a crisis and how each treats the people aboard. Whose leadership is better suited to the voyage? Answer in 80-120 words.', model: 'Captain Rao leads by command and works alone. The narrator works with others: the crewmen pump, Mary raises the alarm and he patches the damage and finds the way. Rao keeps his crew in the dark, while the narrator\'s family, even the children, share in the danger and its answer. On a long ordeal, the narrator\'s approach is better suited: it keeps morale up through days of tiredness. A solitary captain may be quick in a single storm but cannot sustain a crew over many days.', sol: 'Two criteria compared (leadership in crisis; treatment of people) + a reasoned judgement of which is better suited. Credit any consistent view.' }));
Q('l_opinion', long({ ...LA, t: 2, d: 4, c: 'evaluation', stem: 'Taking two young children on a voyage like this was reckless. Do you agree? Give reasons from the account in 80-120 words.', model: 'I partly agree. Mary, the narrator and the crew were exposed to real danger, and a huge wave wrecked the deck, so the children were at risk. Yet the family prepared carefully: the boat was professionally built and tested in gales, they reduced sail and practised with the life raft, and two crewmen came for the hardest part. The children also showed courage that helped everyone. The voyage was risky, but not careless; the real lesson is that preparation, not luck, makes a family brave.', sol: 'A clear stand; evidence on both sides (the danger; the preparation); a conclusion. Credit a reasoned total agreement or disagreement.' }));
Q('l_compare', long({ ...LA, t: 3, d: 4, c: 'analysis', stem: 'Compare how fear and courage are shown by the adults and by the children in the account, with two incidents for each group. Which group\'s courage do you find harder to practise, and why? Answer in 80-120 words.', model: 'The adults show courage by action: Larry and Herb pump for hours and the narrator patches the deck and then works out the boat\'s position. The children show it by feeling: Suzanne hides her injury so as not to worry her parents, and Jonathan says that being together matters more than being afraid. I find the children\'s courage harder, because it asks them to hold back their own needs with no task to take their mind off the danger, while the adults at least have work to do.', sol: 'Two incidents per group; comparison of action and feeling; a reasoned judgement of which is harder. Credit any consistent view.' }));
